function parseNlbwToJson(raw) {
    const output = [];
    const lines = raw.split(/\r?\n/);

    const regex = /^\s*,?\s*(IPv4|IPv6)\s+(\d+\.\d+\.\d+\.\d+)\s+\(([\da-f:]+)\)\s+(\w+)\s+([\d.,]+\s*[KMG]?)\s+([\d.,]+\s*[KMG]?B)\s+\(\s*([\d.,]+\s*[KMG]?)\s*\)\s+([\d.,]+\s*[KMG]?B)\s+\(\s*([\d.,]+\s*[KMG]?)\s*\)/i;

    for (const line of lines) {
        if (!line.trim() || line.startsWith('=') || line.includes('Fam')) continue;

        const match = line.match(regex);
        if (!match) continue;

        const [
            , family, ip, mac, protocol,
            connections,
            downloadBytes, downloadPkts,
            uploadBytes, uploadPkts
        ] = match;

        output.push({
            ip,
            mac,
            protocol,
            connections: parseInt(normalizeNumber(connections)),
            download: {
                bytes: convertToBytes(downloadBytes),
                packets: convertToPackets(downloadPkts)
            },
            upload: {
                bytes: convertToBytes(uploadBytes),
                packets: convertToPackets(uploadPkts)
            }
        });
    }

    return output;
}

// --- Helper functions ---

function normalizeNumber(val) {
    return val.trim().replace(/,/g, '').replace(/\s+/g, '');
}

function convertToPackets(str) {
    const match = normalizeNumber(str).match(/([\d.]+)([KMG]?)/i);
    if (!match) return 0;
    const num = parseFloat(match[1]);
    const unit = match[2].toUpperCase();
    const scale = { '': 1, K: 1e3, M: 1e6, G: 1e9 };
    return Math.round(num * (scale[unit] || 1));
}

function convertToBytes(str) {
    const match = normalizeNumber(str).match(/([\d.]+)([KMG]?B)/i);
    if (!match) return 0;
    const num = parseFloat(match[1]);
    const unit = match[2].toUpperCase();
    const scale = { B: 1, KB: 1e3, MB: 1e6, GB: 1e9 };
    return Math.round(num * (scale[unit] || 1));
}

