const lines = msg.session.stdout.join('').split('\n');
const timestamp = new Date().toISOString();
const results = [];

for (const line of lines) {
    if (!line.includes('src=192.168')) continue;

    const srcMatch = line.match(/src=([0-9.]+)/);
    const dstMatch = line.match(/dst=([0-9.]+)/);
    const sportMatch = line.match(/sport=(\d+)/);
    const dportMatch = line.match(/dport=(\d+)/);
    const protoMatch = line.match(/\s(tcp|udp|icmp)\s/);
    const stateMatch = line.match(/\s(ESTABLISHED|TIME_WAIT|CLOSE_WAIT|SYN_SENT|SYN_RECV|FIN_WAIT1|FIN_WAIT2|LAST_ACK|CLOSED|LISTEN)\s/);
    const bytesSentMatch = line.match(/bytes=(\d+)/); // First occurrence is client→server
    const bytesReceivedMatch = [...line.matchAll(/bytes=(\d+)/g)][1]; // Second occurrence = server→client
    const natDstMatch = line.match(/dport=\d+.*?src=([0-9.]+)/); // NAT'd destination IP
    const assured = line.includes('[ASSURED]');
    const timeoutMatch = line.match(/\s(\d+)\s(ESTABLISHED|CLOSE|.*)\s/); // First number = timeout in seconds

    if (srcMatch && dstMatch) {
        results.push({
            timestamp,
            protocol: protoMatch ? protoMatch[1] : null,
            state: stateMatch ? stateMatch[1] : null,
            src_ip: srcMatch[1],
            src_port: sportMatch ? parseInt(sportMatch[1]) : null,
            dst_ip: dstMatch[1],
            dst_port: dportMatch ? parseInt(dportMatch[1]) : null,
            nat_translated_ip: natDstMatch ? natDstMatch[1] : null,
            bytes_sent: bytesSentMatch ? parseInt(bytesSentMatch[1]) : null,
            bytes_received: bytesReceivedMatch ? parseInt(bytesReceivedMatch[1]) : null,
            timeout_sec: timeoutMatch ? parseInt(timeoutMatch[1]) : null,
            assured: assured
        });
    }
}

return {
    payload : results
};

