let cache = [];
try {
    cache = JSON.parse(msg.payload);
} catch (e) { }

const currentList = msg.data || [];
const previousMap = new Map(cache.map(e => [`${e.ip}_${e.protocol}`, e]));

// Update cache with current values (overwrite or insert)
for (const curr of currentList) {
    const key = `${curr.ip}_${curr.protocol}`;
    previousMap.set(key, curr);
}

// Convert updated map back to array
const updatedCache = Array.from(previousMap.values());

// Calculate deltas
const deltas = [];
for (const curr of currentList) {
    const key = `${curr.ip}_${curr.protocol}`;
    const prev = cache.find(e => `${e.ip}_${e.protocol}` === key);

    if (prev) {
        const deltaUploadBytes = curr.upload.bytes - prev.upload.bytes;
        const deltaUploadPackets = curr.upload.packets - prev.upload.packets;
        const deltaDownloadBytes = curr.download.bytes - prev.download.bytes;
        const deltaDownloadPackets = curr.download.packets - prev.download.packets;

        // Skip if reset occurred (negative deltas)
        if (
            deltaUploadBytes < 0 ||
            deltaUploadPackets < 0 ||
            deltaDownloadBytes < 0 ||
            deltaDownloadPackets < 0
        ) {
            continue; // Detected a reset — skip this delta
        }

        const delta = {
            ip: curr.ip,
            protocol: curr.protocol,
            upload: {
                bytes: deltaUploadBytes,
                packets: deltaUploadPackets
            },
            download: {
                bytes: deltaDownloadBytes,
                packets: deltaDownloadPackets
            }
        };

        if (
            delta.upload.bytes > 0 ||
            delta.upload.packets > 0 ||
            delta.download.bytes > 0 ||
            delta.download.packets > 0
        ) {
            deltas.push(delta);
        }
    }
}

return [
    { payload: deltas },          // Output 1: traffic delta (for DB, MQTT, etc.)
    { payload: updatedCache }     // Output 2: new cache to write back to file
];

